// 1. Input Validation
if (wp_config.trip_filtered_w <= wp_config.release_filtered_w ||
    wp_config.filter_alpha < 0.0 || wp_config.filter_alpha > 1.0 ||
    wp_config.motoring_limit_w <= 0.0 ||
    wp_config.regenerative_limit_w <= 0.0 ||
    wp_config.max_torque_slew_nm_per_cycle <= 0.0 ||
    wp_config.release_cycles < 1 || wp_config.release_cycles > 20) {

    wp_state.mode = WP_FAULT;
    wp_state.clean = 0;
    wp_state.filtered_abs_power_w = 0.0;

    wp_output.mode = WP_FAULT;
    wp_output.clean = 0;
    wp_output.power_limited_mask = 0;
    wp_output.slew_limited_mask = 0;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms.x = 0.0;
    wp_output.momentum_nms.y = 0.0;
    wp_output.momentum_nms.z = 0.0;
    wp_output.requested_body_torque_nm.x = 0.0;
    wp_output.requested_body_torque_nm.y = 0.0;
    wp_output.requested_body_torque_nm.z = 0.0;
    wp_output.delivered_body_torque_nm.x = 0.0;
    wp_output.delivered_body_torque_nm.y = 0.0;
    wp_output.delivered_body_torque_nm.z = 0.0;
    for (int i = 0; i < 4; ++i) {
        wp_output.limited_torque_nm[i] = 0.0;
    }
    return;
}

// Initialize state if needed
if (!wp_state.initialized) {
    for (int i = 0; i < 4; ++i) {
        wp_state.previous_torque_nm[i] = 0.0;
    }
    wp_state.filtered_abs_power_w = 0.0;
    wp_state.initialized = 1;
    wp_state.mode = WP_NORMAL;
    wp_state.clean = 0;
}

// 2. Validate Wheels Momentum
adcs_vec3_t momentum;
adcs_status_t status = adcs_wheel_momentum(wp_input.wheels, wp_input.wheel_count, &momentum);
if (status != ADCS_OK) {
    wp_state.mode = WP_FAULT;
    wp_state.clean = 0;
    wp_output.mode = WP_FAULT;
    wp_output.clean = 0;
    wp_output.power_limited_mask = 0;
    wp_output.slew_limited_mask = 0;
    wp_output.requested_net_power_w = 0.0;
    wp_output.delivered_net_power_w = 0.0;
    wp_output.requested_motoring_power_w = 0.0;
    wp_output.requested_regenerative_power_w = 0.0;
    wp_output.delivered_motoring_power_w = 0.0;
    wp_output.delivered_regenerative_power_w = 0.0;
    wp_output.filtered_abs_power_w = 0.0;
    wp_output.momentum_norm_nms = 0.0;
    wp_output.momentum_nms.x = 0.0;
    wp_output.momentum_nms.y = 0.0;
    wp_output.momentum_nms.z = 0.0;
    wp_output.requested_body_torque_nm.x = 0.0;
    wp_output.requested_body_torque_nm.y = 0.0;
    wp_output.requested_body_torque_nm.z = 0.0;
    wp_output.delivered_body_torque_nm.x = 0.0;
    wp_output.delivered_body_torque_nm.y = 0.0;
    wp_output.delivered_body_torque_nm.z = 0.0;
    for (int i = 0; i < 4; ++i) {
        wp_output.limited_torque_nm[i] = 0.0;
    }
    return;
}

double orig_torque_nm[4];
double constrained_torque_nm[4];
double raw_mot_power = 0.0;
double raw_reg_power = 0.0;
double raw_net_power = 0.0;

// 3. Calculate Raw Powers and Store Original Torques
for (int i = 0; i < 4; ++i) {
    orig_torque_nm[i] = wp_input.torque_nm[i];
    double speed = wp_input.wheels[i].speed_rad_s;
    double power = orig_torque_nm[i] * speed;
    raw_net_power += power;
    if (power > 0.0) {
        raw_mot_power += power;
    } else {
        raw_reg_power += fabs(power);
    }
}

// 4. Scale Torques to Meet Power Limits
unint32 power_limited_mask = 0;

// Motoring Scaling
if (raw_mot_power > wp_config.motoring_limit_w) {
    double scale = wp_config.motoring_limit_w / raw_mot_power;
    for (int i = 0; i < 4; ++i) {
        double speed = wp_input.wheels[i].speed_rad_s;
        if (orig_torque_nm[i] * speed > 0.0) {
            constrained_torque_nm[i] = orig_torque_nm[i] * scale;
            power_limited_mask |= (1U << i);
        } else {
            constrained_torque_nm[i] = orig_torque_nm[i];
        }
    }
} else {
    for (int i = 0; i < 4; ++i) {
        constrained_torque_nm[i] = orig_torque_nm[i];
    }
}

// Regenerative Scaling
if (raw_reg_power > wp_config.regenerative_limit_w) {
    double scale = wp_config.regenerative_limit_w / raw_reg_power;
    for (int i = 0; i < 4; ++i) {
        double speed = wp_input.wheels[i].speed_rad_s;
        if (orig_torque_nm[i] * speed < 0.0) {
            constrained_torque_nm[i] = orig_torque_nm[i] * scale;
            power_limited_mask |= (1U << i);
        }
    }
}

// 5. Slew Limiting and Body Torque Calculation
unint32 slew_limited_mask = 0;
double delivered_torque_nm[4];
adcs_vec3_t requested_body_torque_nm = {0.0, 0.0, 0.0};
adcs_vec3_t delivered_body_torque_nm = {0.0, 0.0, 0.0};

for (int i = 0; i < 4; ++i) {
    double prev = wp_state.previous_torque_nm[i];
    double diff = constrained_torque_nm[i] - prev;

    // Add to Requested Body Torque
    adcs_vec3_t axis = wp_input.wheels[i].axis_body;
    adcs_vec3_t term = adcs_vec3_scale(&axis, -constrained_torque_nm[i]);
    requested_body_torque_nm = adcs_vec3_add(&requested_body_torque_nm, &term);

    if (fabs(diff) > wp_config.max_torque_slew_nm_per_cycle) {
        slew_limited_mask |= (1U << i);
        if (diff > 0) {
            delivered_torque_nm[i] = prev + wp_config.max_torque_slew_nm_per_cycle;
        } else {
            delivered_torque_nm[i] = prev - wp_config.max_torque_slew_nm_per_cycle;
        }
    } else {
        delivered_torque_nm[i] = constrained_torque_nm[i];
    }

    // Add to Delivered Body Torque
    term = adcs_vec3_scale(&axis, -delivered_torque_nm[i]);
    delivered_body_torque_nm = adcs_vec3_add(&delivered_body_torque_nm, &term);
}

// 6. Filter Absolute Net Power
double abs_net_power = fabs(raw_net_power);
double filtered_abs_power_w = wp_config.filter_alpha * abs_net_power + (1.0 - wp_config.filter_alpha) * wp_state.filtered_abs_power_w;

// 7. State Machine Transition
int any_limit_active = (power_limited_mask != 0) || (slew_limited_mask != 0);
int trip_triggered = filtered_abs_power_w >= wp_config.trip_filtered_w;

if (any_limit_active || trip_triggered) {
    wp_state.mode = WP_LIMITED;
    wp_state.clean = 0;
} else {
    if (wp_state.mode == WP_RECOVERING) {
        wp_state.clean++;
        if (wp_state.clean >= wp_config.release_cycles) {
            wp_state.mode = WP_NORMAL;
            wp_state.clean = 0;
        }
    } else {
        // If NORMAL or other non-LIMITED states without triggers, stay NORMAL
        wp_state.mode = WP_NORMAL;
        wp_state.clean = 0;
    }
}

// Update persistent state
wp_state.filtered_abs_power_w = filtered_abs_power_w;
for (int i = 0; i < 4; ++i) {
    wp_state.previous_torque_nm[i] = delivered_torque_nm[i];
}

// 8. Populate Output
wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;
wp_output.power_limited_mask = power_limited_mask;
wp_output.slew_limited_mask = slew_limited_mask;

// Requested Powers (based on constrained torques)
double req_mot = 0.0, req_reg = 0.0;
double req_net = 0.0;
for (int i = 0; i < 4; ++i) {
    double p = constrained_torque_nm[i] * wp_input.wheels[i].speed_rad_s;
    req_net += p;
    if (p > 0.0) req_mot += p;
    else req_reg += fabs(p);
}
wp_output.requested_net_power_w = req_net;
wp_output.requested_motoring_power_w = req_mot;
wp_output.requested_regenerative_power_w = req_reg;

// Delivered Powers (based on slew-limited torques)
double del_mot = 0.0, del_reg = 0.0;
double del_net = 0.0;
for (int i = 0; i < 4; ++i) {
    double p = delivered_torque_nm[i] * wp_input.wheels[i].speed_rad_s;
    del_net += p;
    if (p > 0.0) del_mot += p;
    else del_reg += fabs(p);
}
wp_output.delivered_net_power_w = del_net;
wp_output.delivered_motoring_power_w = del_mot;
wp_output.delivered_regenerative_power_w = del_reg;

wp_output.filtered_abs_power_w = filtered_abs_power_w;

wp_output.momentum_nms = momentum;
wp_output.momentum_norm_nms = adcs_vec3_norm(&momentum);
wp_output.requested_body_torque_nm = requested_body_torque_nm;
wp_output.delivered_body_torque_nm = delivered_body_torque_nm;

for (int i = 0; i < 4; ++i) {
    wp_output.limited_torque_nm[i] = delivered_torque_nm[i];
}

