double final_delivered_net = 0.0;

for (int i = 0; i < 4; i++) {
    double fp = final_torques[i] * wp_input.wheels[i].speed_rad_s;
    if (fp > 0.0) {
        final_delivered_motoring += fp;
    } else {
        final_delivered_regenerative += fabs(fp);
    }
    final_delivered_net += fp;
}

// Update state for next cycle
for (int i = 0; i < 4; i++) {
    wp_state.previous_torque_nm[i] = final_torques[i];
}

// 7. State Machine Logic
int is_power_limited = (power_limited_mask != 0);
int is_slew_limited = (slew_limited_mask != 0);
int is_high_power = (filtered_power >= wp_config.trip_filtered_w);
int is_in_limit_state = is_power_limited || is_slew_limited || is_high_power;

if (is_in_limit_state) {
    wp_state.mode = WP_LIMITED;
    wp_state.clean = 0;
} else {
    if (wp_state.mode == WP_NORMAL) {
        wp_state.mode = (wp_mode_t)WP_NORMAL;
        wp_state.clean = 0U;
    } else if (wp_state.mode == WP_LIMITED) {
        wp_state.mode = (wp_mode_t)WP_RECOVERING;
        wp_state.clean = 1U;
    } else if (wp_state.mode == WP_RECOVERING) {
        if (filtered_power <= wp_config.release_filtered_w) {
            wp_state.clean++;
            if (wp_state.clean >= wp_config.release_cycles) {
                wp_state.mode = (wp_mode_t)WP_NORMAL;
                wp_state.clean = 0U;
            }
        } else {
            wp_state.clean = 0U;
        }
    } else {
        wp_state.mode = (wp_mode_t)WP_FAULT;
        wp_state.clean = 0U;
    }
}

// 8. Compute Body Torques
adcs_vec3_t req_body_torque = {0,0,0};
adcs_vec3_t del_body_torque = {0,0,0};

for (int i = 0; i < 4; i++) {
    adcs_vec3_t axis = wp_input.wheels[i].axis_body;
    adcs_vec3_t t_req = adcs_vec3_scale(&axis, -req_torques[i]);
    req_body_torque = adcs_vec3_add(&req_body_torque, &t_req);

    adcs_vec3_t t_del = adcs_vec3_scale(&axis, -final_torques[i]);
    del_body_torque = adcs_vec3_add(&del_body_torque, &t_del);
}

// 9. Populate Output
wp_output.mode = wp_state.mode;
wp_output.clean = wp_state.clean;
wp_output.power_limited_mask = power_limited_mask;
wp_output.slew_limited_mask = slew_limited_mask;
wp_output.requested_net_power_w = requested_net_p;
wp_output.delivered_net_power_w = final_delivered_net;
wp_output.requested_motoring_power_w = requested_motoring_p;
wp_output.requested_regenerative_power_w = requested_regenerative_p;
wp_output.delivered_motoring_power_w = final_delivered_motoring;
wp_output.delivered_regenerative_power_w = final_delivered_regenerative;
wp_output.filtered_abs_power_w = filtered_power;

for (int i = 0; i < 4; i++) {
    wp_output.limited_torque_nm[i] = final_torques[i];
}

wp_output.momentum_nms = momentum;
wp_output.momentum_norm_nms = adcs_vec3_norm(&momentum);
wp_output.requested_body_torque_nm = req_body_torque;
wp_output.delivered_body_torque_nm = del_body_torque;
